function pair(left: f64[], right: f64[]): f64 {
  left.length = 0;
  return right[0];
}
export function entry(): f64 {
  const a: f64[] = [1.0];
  const same = a;
  const v: ReadSpan<f64> = readSpan(a, 0, 1);
  pair(a, same);
  return v[0];
}

